{
  "round_analysis": "Round 0 has no empirical feedback, so the strategy is to maximize diversity and effective rank of the LUSI kernel descriptors. The non-collapse gate requires d>=3 weakly correlated channels (participation ratio >=1.25, off-diagonal cosine <0.98 vs 11^T/B). I therefore design symbolic predicates that mix (a) distinct time operators (slope, semivar_asymmetry, hurst_proxy, autocorr_1, path_efficiency, ema_diff, q_spread) over (b) distinct Alpha158 subspaces (KBar morphology [0,9], price/VWAP [9,29], momentum/vol/trend [29,95], volume/order-flow [95,158]) and (c) cross-slice interactions (diff/ratio/corr/lead_lag_corr) to decorrelate channels. Windows span 3..20. A minority of proposals use novel operator primitives (semivar_ratio, vol_price_corr, path_efficiency, hurst_vr, lead_lag_beta, regime_transition, tail_asymmetry) and a few composites, keeping >=75% on symbolic/operator families. Rationale: residual heteroskedasticity and asymmetric response to volume/order-flow shocks are not captured by plain MSE; statistical-invariant kernels that weight residuals by realized semivariance asymmetry, path efficiency, and price-volume lead-lag should align residuals cross-sectionally and raise daily IC.",
  "proposals": [
    {
      "kind": "statistical",
      "name": "kbar_semivar_volume_coupling",
      "rationale": "Intraday candlestick asymmetry (upper vs lower shadow) combined with semivariance asymmetry and volume-weighted volatility should identify stocks whose residual variance is regime-dependent, aligning LUSI residuals with order-flow shocks.",
      "descriptor": {
        "family": "symbolic",
        "params": {"window": 10},
        "channels": [
          {"time_op": "semivar_asymmetry", "feature_op": "mean", "window": 10, "feature_slice": [0, 9], "interaction": "none", "transform": "tanh", "weight": 1.0},
          {"time_op": "std", "feature_op": "top_bottom_spread", "window": 8, "feature_slice": [95, 158], "interaction": "ratio", "rhs_slice": [9, 29], "rhs_time_op": "mean", "rhs_window": 8, "transform": "identity", "weight": 0.9},
          {"time_op": "slope", "feature_op": "iqr", "window": 12, "feature_slice": [29, 95], "interaction": "diff", "rhs_slice": [95, 158], "rhs_time_op": "ema_diff", "rhs_window": 12, "transform": "abs", "weight": 1.1}
        ]
      }
    },
    {
      "kind": "statistical",
      "name": "path_efficiency_momentum_leadlag",
      "rationale": "Path efficiency of momentum features vs lead-lag beta of volume on price captures trend persistence and information flow; residual weighting should emphasize stocks with coherent directional paths.",
      "descriptor": {
        "family": "symbolic",
        "params": {"window": 15},
        "channels": [
          {"time_op": "path_efficiency", "feature_op": "l2_norm", "window": 15, "feature_slice": [29, 95], "interaction": "none", "transform": "identity", "weight": 1.2},
          {"time_op": "autocorr_1", "feature_op": "mean", "window": 12, "feature_slice": [95, 158], "interaction": "corr", "rhs_slice": [9, 29], "rhs_time_op": "slope", "rhs_window": 12, "transform": "tanh", "weight": 0.8},
          {"time_op": "hurst_proxy", "feature_op": "std", "window": 18, "feature_slice": [29, 95], "interaction": "none", "transform": "sign_sqrt", "weight": 0.9}
        ]
      }
    },
    {
      "kind": "statistical",
      "name": "skew_qspread_orderflow",
      "rationale": "Return skewness and quantile spread of price channels coupled with order-flow imbalance should capture tail-risk asymmetry where MSE residuals are largest.",
      "descriptor": {
        "family": "symbolic",
        "params": {"window": 12},
        "channels": [
          {"time_op": "skew", "feature_op": "mean", "window": 12, "feature_slice": [29, 95], "interaction": "none", "transform": "tanh", "weight": 1.0},
          {"time_op": "q_spread", "feature_op": "iqr", "window": 10, "feature_slice": [9, 29], "interaction": "ratio", "rhs_slice": [95, 158], "rhs_time_op": "std", "rhs_window": 10, "transform": "identity", "weight": 0.9},
          {"time_op": "ema_diff", "feature_op": "top_bottom_spread", "window": 6, "feature_slice": [95, 158], "interaction": "none", "transform": "abs", "weight": 1.1}
        ]
      }
    },
    {
      "kind": "statistical",
      "name": "drawdown_vol_price_corr",
      "rationale": "Max drawdown of price channels and volume-price correlation identify stress regimes; residual variance is amplified in drawdown states, so kernel should upweight them.",
      "descriptor": {
        "family": "symbolic",
        "params": {"window": 20},
        "channels": [
          {"time_op": "max_drawdown", "feature_op": "min", "window": 20, "feature_slice": [9, 29], "interaction": "none", "transform": "abs", "weight": 1.2},
          {"time_op": "std", "feature_op": "corr_half", "window": 15, "feature_slice": [95, 158], "interaction": "corr", "rhs_slice": [29, 95], "rhs_time_op": "mean", "rhs_window": 15, "transform": "identity", "weight": 0.9},
          {"time_op": "accel", "feature_op": "std", "window": 12, "feature_slice": [29, 95], "interaction": "none", "transform": "tanh", "weight": 1.0}
        ]
      }
    },
    {
      "kind": "statistical",
      "name": "kurt_volume_leadlag_beta",
