      "descriptor": {
        "family": "symbolic",
        "params": {"window": 10},
        "channels": [
          {"time_op": "kurt", "feature_op": "mean", "window": 10, "feature_slice": [29, 95], "interaction": "none", "transform": "sign_sqrt", "weight": 1.0},
          {"time_op": "slope", "feature_op": "top_bottom_spread", "window": 8, "feature_slice": [95, 158], "interaction": "lead_lag_corr", "rhs_slice": [9, 29], "rhs_time_op": "mean", "rhs_window": 8, "transform": "tanh", "weight": 1.1},
