          {"time_op": "std", "feature_op": "corr_half", "window": 6, "feature_slice": [95, 158], "interaction": "corr", "rhs_slice": [9, 29], "rhs_time_op": "slope", "rhs_window": 6, "transform": "tanh", "weight": 1.1},
